// Ajusta mimetype e nome do arquivo para OGG Opus

return items.map(item => {
  const binary = item.binary;

  if (binary && binary.data) {
    binary.data.mimeType = 'audio/ogg; codecs=opus';
    binary.data.fileName = 'output.ogg';
  }

  return {
    json: item.json,
    binary
  };
});

