const now = new Date();
const local = new Date(
  now.toLocaleString("en-US", { timeZone: "America/Fortaleza" })
);

const day = local.getDay();
const hours = local.getHours().toString().padStart(2, "0");
const minutes = local.getMinutes().toString().padStart(2, "0");

const currentMinutes = parseInt(hours) * 60 + parseInt(minutes);

let lojaOpen = false;

// Segunda a sexta: 05h–22h
if (day >= 1 && day <= 5) {
  lojaOpen = currentMinutes >= 300 && currentMinutes < 1320;
}
// Sábado: 08h–18h
else if (day === 6) {
  lojaOpen = currentMinutes >= 480 && currentMinutes < 1080;
}
// Domingo: 09h–13h
else if (day === 0) {
  lojaOpen = currentMinutes >= 540 && currentMinutes < 780;
}

const estado = lojaOpen ? "A" : "C";

return [
  {
    json: {
      estado,
      horaAtual: `${hours}:${minutes}`,
      diaSemana: day,
    },
  },
];
